'use strict';

// Draws the extension icon: three bars on the Claude orange, as a 128x128 PNG,
// with nothing but zlib. The Marketplace wants a PNG and the repo wants no
// image tooling, so the icon is generated by the build.

const fs = require('fs');
const zlib = require('zlib');

const SIZE = 128;
const BACKGROUND = [215, 119, 87];
const BAR = [255, 255, 255];
// x, y, width, height, matching media/icon.svg.
const BARS = [
  [20, 26, 88, 18],
  [20, 55, 60, 18],
  [20, 84, 36, 18],
];

function crc32(buffer) {
  let crc = ~0;
  for (const byte of buffer) {
    crc ^= byte;
    for (let k = 0; k < 8; k += 1) crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
  }
  return ~crc >>> 0;
}

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([length, body, crc]);
}

function inside(x, y) {
  return BARS.some(([bx, by, bw, bh]) => x >= bx && x < bx + bw && y >= by && y < by + bh);
}

function png() {
  const rows = [];
  for (let y = 0; y < SIZE; y += 1) {
    const row = Buffer.alloc(1 + SIZE * 4);
    row[0] = 0;
    for (let x = 0; x < SIZE; x += 1) {
      const colour = inside(x, y) ? BAR : BACKGROUND;
      const at = 1 + x * 4;
      row[at] = colour[0];
      row[at + 1] = colour[1];
      row[at + 2] = colour[2];
      row[at + 3] = 255;
    }
    rows.push(row);
  }
  const header = Buffer.alloc(13);
  header.writeUInt32BE(SIZE, 0);
  header.writeUInt32BE(SIZE, 4);
  header[8] = 8;
  header[9] = 6;
  header[10] = 0;
  header[11] = 0;
  header[12] = 0;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', header),
    chunk('IDAT', zlib.deflateSync(Buffer.concat(rows))),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

function write(file) {
  fs.writeFileSync(file, png());
  return file;
}

module.exports = { png, write, SIZE };

if (require.main === module) {
  write(process.argv[2] || require('path').join(__dirname, 'icon.png'));
}
